// Spoonful i18n - full UI translation system.
// Covers every interface string in 9 languages. Recipe content (titles,
// ingredients, steps from the catalogs / user recipes) is intentionally
// NOT translated.

import { I18nManager } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { FEATURES } from './i18n-features';
import { AR } from './i18n-ar';
import { APP_212 } from './i18n-212';
import { UI_L10N } from './i18n-ui';
import { SCREENS_L10N } from './i18n-screens';

export type Language = "en" | "de" | "ar" | "fr" | "es" | "it" | "tr" | "pt" | "nl" | "ru";

export const LANGUAGES: { code: Language; name: string; native: string }[] = [
  { code: "en", name: "English", native: "English" },
  { code: "de", name: "German", native: "Deutsch" },
  { code: "ar", name: "Arabic", native: "العربية" },
  { code: "fr", name: "French", native: "Français" },
  { code: "es", name: "Spanish", native: "Español" },
  { code: "it", name: "Italian", native: "Italiano" },
  { code: "tr", name: "Turkish", native: "Türkçe" },
  { code: "pt", name: "Portuguese", native: "Português" },
  { code: "nl", name: "Dutch", native: "Nederlands" },
  { code: "ru", name: "Russian", native: "Русский" },
];

/** Arabic (and the other RTL scripts) flip the whole layout direction. */
export const RTL_LANGUAGES: Language[] = ["ar"];
export function isRtlLanguage(lang: Language): boolean {
  return RTL_LANGUAGES.includes(lang);
}

const STORAGE_KEY = "spoonful-lang";
const DEVICE_LANG_SEEN = "spoonful-lang-from-device";

let cachedLanguage: Language | null = null;
/** True when the language came from the device on the very first start. */
let languageFromDevice = false;
/** True when the layout direction changed and needs an app restart. */
let restartRequired = false;
/** True when the device language is not one of the 10 supported languages. */
let deviceLangUnsupported = false;
/** True once the language picker was shown for an unsupported device language. */
let langPickerShown = false;

export function markLanguagePickerShown(): void {
  langPickerShown = true;
}

export function wasLanguagePickerShown(): boolean {
  return langPickerShown;
}

/** Synchronous read — fast path after the first hydration. */
export function getStoredLanguage(): Language {
  return cachedLanguage ?? "en";
}

export function wasLanguageFromDevice(): boolean {
  return languageFromDevice;
}

export function isRestartRequired(): boolean {
  return restartRequired;
}

/**
 * 2.1.2: language of the device, without any native dependency.
 * Android exposes it through I18nManager.localeIdentifier, iOS through
 * SettingsManager; Intl is the last fallback (Hermes ships it).
 */
export function detectDeviceLanguage(): Language | null {
  const candidates: string[] = [];
  try {
    const native = require("react-native").NativeModules as any;
    const id = native?.I18nManager?.localeIdentifier ?? native?.SettingsManager?.settings?.AppleLocale;
    if (typeof id === "string") candidates.push(id);
  } catch { /* ignore */ }
  try {
    const intl = (Intl as any)?.DateTimeFormat?.().resolvedOptions?.().locale;
    if (typeof intl === "string") candidates.push(intl);
  } catch { /* ignore */ }

  for (const raw of candidates) {
    // "de_DE", "de-AT", "zh-Hans-CN" -> primary subtag
    const code = raw.replace("_", "-").split("-")[0].toLowerCase();
    if (LANGUAGES.some((l) => l.code === code)) return code as Language;
    // Arabic dialects (ar-EG, fa, he, ur) all read right to left
    if (["fa", "he", "ur", "ar"].includes(code)) return "ar";
  }
  return null;
}

/** Async initial hydration from storage (call once at app start). */
export async function hydrateStoredLanguage(): Promise<Language> {
  try {
    const stored = await AsyncStorage.getItem(STORAGE_KEY);
    if (stored && LANGUAGES.some((l) => l.code === stored)) {
      cachedLanguage = stored as Language;
      return stored as Language;
    }
    // 2.1.2: no choice stored yet -> take the device language right away.
    const device = detectDeviceLanguage();
    if (device) {
      cachedLanguage = device;
      languageFromDevice = true;
      await AsyncStorage.setItem(STORAGE_KEY, device);
      await AsyncStorage.setItem(DEVICE_LANG_SEEN, "1");
      return device;
    }
    cachedLanguage = "en";
    // Device language unknown/unsupported: remember that we may ask gently once.
    deviceLangUnsupported = true;
    await AsyncStorage.setItem(DEVICE_LANG_SEEN, "ask");
  } catch { /* ignore */ }
  return cachedLanguage ?? "en";
}

/** 2.1.2: the device language is not one of ours - we show a soft hint once. */
export function deviceLanguageNeedsChoice(): boolean {
  return deviceLangUnsupported;
}

export async function clearDeviceLanguageAsk(): Promise<void> {
  deviceLangUnsupported = false;
  try { await AsyncStorage.setItem(DEVICE_LANG_SEEN, "1"); } catch { /* ignore */ }
}

/** Reads the stored marker at start-up (so the hint survives a restart). */
export async function loadDeviceLanguageAsk(): Promise<boolean> {
  try {
    const v = await AsyncStorage.getItem(DEVICE_LANG_SEEN);
    deviceLangUnsupported = v === "ask";
  } catch { /* ignore */ }
  return deviceLangUnsupported;
}

/** Arabic is right-to-left: the app flips the layout direction for it. */
export function applyLayoutDirection(lang: Language) {
  try {
    const rtl = isRtlLanguage(lang);
    I18nManager.allowRTL(true);
    if (I18nManager.isRTL !== rtl) {
      I18nManager.forceRTL(rtl);
      // Changing the direction only takes full effect after a restart.
      restartRequired = true;
    }
  } catch { /* ignore */ }
}

export function setLanguage(lang: Language) {
  cachedLanguage = lang;
  try { AsyncStorage.setItem(STORAGE_KEY, lang).catch(() => {}); } catch { /* ignore */ }
  applyLayoutDirection(lang);
}

/**
 * 2.1.2: RTL helper for components. `I18nManager.isRTL` only flips after a
 * restart, so screens can mirror instantly with these helpers.
 */
export function isRtlActive(lang?: Language): boolean {
  const l = lang ?? getStoredLanguage();
  try {
    return isRtlLanguage(l) || I18nManager.isRTL;
  } catch {
    return isRtlLanguage(l);
  }
}

/** Mirrored row / text style — use in new components instead of hard "row". */
export function rtlRow(lang?: Language) {
  const rtl = isRtlActive(lang);
  return {
    flexDirection: (rtl ? "row-reverse" : "row") as "row" | "row-reverse",
    textAlign: (rtl ? "right" : "left") as "right" | "left",
  };
}

/**
 * 2.1.2: try to reload the JS bundle after a direction change.
 * Works in debug builds (DevSettings) and is a silent no-op in release builds,
 * where the user simply closes and reopens the app (the popup says so).
 */
export function tryReloadApp(): boolean {
  try {
    const rn = require("react-native") as any;
    if (rn?.DevSettings?.reload) {
      rn.DevSettings.reload();
      return true;
    }
  } catch {
    /* release build: no DevSettings */
  }
  return false;
}


