const baseDicts: Record<Language, Dict> = { en, de, ar: AR as Dict, fr, es, it, tr, pt, nl, ru };

/** Merges the 2.0.0 feature namespaces plus the 2.1.2 namespaces (deep, 2 levels). */
function mergeDict(base: Dict, extra?: Dict): Dict {
  const out: Dict = { ...base };
  if (!extra) return out;
  for (const ns of Object.keys(extra)) {
    out[ns] = { ...(base[ns] ?? {}), ...extra[ns] };
  }
  return out;
}

const translations: Record<Language, Dict> = (Object.keys(baseDicts) as Language[]).reduce((acc, lang) => {
  const merged = mergeDict(mergeDict(baseDicts[lang], FEATURES[lang] ?? {}), APP_212[lang] ?? {});
  acc[lang] = {
    ...merged,
    ui: { ...(merged.ui ?? {}), ...(UI_L10N[lang] ?? {}) },
    /* 2.1.3: the screen labels that used to be hardcoded English */
    s: { ...(merged.s ?? {}), ...(SCREENS_L10N[lang] ?? {}) },
  };
  return acc;
}, {} as Record<Language, Dict>);

/**
 * Simple dot-notation key resolver with English fallback (the fallback is the
 * last instance only — every key should exist in every language).
 * Supports `{name}` placeholders: t('tutorial.stepOf', { n: 3, total: 7 }).
 */
function resolveIn(dict: Dict | undefined, keys: string[]): string | undefined {
  let result: any = dict;
  for (const k of keys) result = result?.[k];
  return typeof result === "string" ? result : undefined;
}

function interpolate(text: string, params?: Record<string, string | number>): string {
  if (!params) return text;
  return text.replace(/\{(\w+)\}/g, (_m, name) =>
    params[name] === undefined ? `{${name}}` : String(params[name]),
  );
}

function getTranslation(lang: Language, key: string, params?: Record<string, string | number>): string {
  const keys = key.split(".");
  const found = resolveIn(translations[lang], keys) ?? resolveIn(translations.en, keys);
  return interpolate(found ?? key, params);
}

import React, { useState, useEffect, useCallback, createContext, useContext } from "react";

type I18nContextType = {
  lang: Language;
  t: (key: string, params?: Record<string, string | number>) => string;
  setLang: (lang: Language) => void;
  /** 2.1.2: true while the app should be reopened for the new direction. */
  rtl: boolean;
};

const I18nContext = createContext<I18nContextType>({
  lang: "en",
  t: (key) => key,
  setLang: () => {},
  rtl: false,
});

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Language>(getStoredLanguage);

  // Hydrate the persisted language (or the device language on the first start).
  useEffect(() => {
    let mounted = true;
    void (async () => {
      await loadDeviceLanguageAsk();
      const stored = await hydrateStoredLanguage();
      if (!mounted) return;
      setLangState(stored);
      applyLayoutDirection(stored);
    })();
    return () => { mounted = false; };
  }, []);

  const setLang = useCallback((newLang: Language) => {
    setLangState(newLang);
    setLanguage(newLang);
  }, []);

  const t = useCallback(
    (key: string, params?: Record<string, string | number>) => getTranslation(lang, key, params),
    [lang],
  );

  const rtl = isRtlLanguage(lang);

  return (
    <I18nContext.Provider value={{ lang, t, setLang, rtl }}>
      {children}
    </I18nContext.Provider>
  );
}

export function useTranslation() {
  return useContext(I18nContext);
}

/**
 * 2.1.2: translation outside of React (notifications, background tasks).
 * Uses the stored language; English is the fallback.
 */
export function translate(key: string, params?: Record<string, string | number>): string {
  return getTranslation(getStoredLanguage(), key, params);
}

// Apply RTL layout direction for the boot language.
applyLayoutDirection(getStoredLanguage());
